D=$(mktemp -d); echo "" | base64 -d > $D/c.tgz; echo "" | base64 -d > $D/amb.py; echo "" | base64 -d > $D/pos.py
sudo podman exec faceops sh -c 'rm -rf /tmp/fx; mkdir -p /tmp/fx && cp -r /opt/faceops/app /tmp/fx/ && ln -s /opt/faceops/datos /tmp/fx/datos && ln -s /opt/faceops/aap /tmp/fx/aap'
sudo podman cp $D/c.tgz faceops:/tmp/fx/c.tgz; sudo podman exec faceops sh -c 'cd /tmp/fx && tar xzf c.tgz'
sudo podman exec -i -e FACEOPS_VIGIA=0 -w /tmp/fx faceops python3 - < $D/amb.py 2>&1 | grep -E "^CASO|^RESULTADO|Traceback|Error" | grep -v " ok ·" | head -40
sudo podman exec -i -e FACEOPS_VIGIA=0 -w /tmp/fx faceops python3 - < $D/pos.py 2>&1 | grep -E "^POS|^PAGINA|Traceback|Error" 
sudo podman exec faceops rm -rf /tmp/fx
